"""Frozen extracted domain kernels. Generated by extract_dm01_domain_r1; no CLI calls."""
from collections import Counter
from decimal import Decimal
import hashlib
import json
from scripts.build_v4_02_price_limits import board_rule_key

def classify_dated_status(row, facts):
    code = row['source_security_key'].lower()
    date = row['trade_date']
    missing_classification = Counter()
    is_st_counts = Counter()
    is_st_security_coverage = set()
    actual_provider_status_conflicts = 0
    actual_provider_status_conflict_rows = []
    if row.get("source_bar_present") is True:
        status = "ACTUAL_TRADED"
        fact = facts.get((code, date))
        status_source = "LOCAL_TDX_BAR_PRESENCE" + ("+BAOSTOCK_DATED_ISST" if fact else "")
        is_st = fact[1] if fact else None
        if fact and fact[0] != "1":
            actual_provider_status_conflicts += 1
            actual_provider_status_conflict_rows.append({"source_security_key": row["source_security_key"],
                                                         "trade_date": date, "provider_tradestatus": fact[0],
                                                         "classification_precedence": "LOCAL_TDX_ACTUAL_BAR_REMAINS_ACTUAL_TRADED"})
    else:
        fact = facts.get((code, date))
        if fact == ("0", "0") or fact == ("0", "1"):
            status = "SUSPENDED"
        elif fact == ("1", "0") or fact == ("1", "1"):
            status = "DATA_GAP"
        else:
            status = "UNKNOWN"
        status_source = "BAOSTOCK_PUBLIC_STATUS_FACT" if fact else "NO_VALID_DATED_PROVIDER_FACT"
        is_st = fact[1] if fact else None
        missing_classification[status] += 1
    if is_st is not None:
        is_st_counts[is_st] += 1
        is_st_security_coverage.add(code)
    output_row = {"security_id": row["security_id"], "source_security_key": row["source_security_key"],
                  "trade_date": date, "status": status, "is_st": is_st,
                  "provider_tradestatus": fact[0] if fact else None, "status_source": status_source}
    return output_row, actual_provider_status_conflict_rows

def dated_isst_fact(member, day, provider_row, binding_revision):
    value = {
        "security_id": member["security_id"],
        "source_security_key": member["source_security_key"],
        "trade_date": day,
        "is_st": provider_row["isST"] if provider_row else None,
        "source_provider": "BAOSTOCK_PUBLIC_ANONYMOUS_QUERY_DAILY_HISTORY_K_ASTOCK",
        "binding_quality": "DIRECT_CODE_DATE" if provider_row else "UNKNOWN_NO_VALID_PROVIDER_ROW",
        "source_revision": binding_revision if provider_row else None,
    }
    return value

def accumulate_period_bar(period_aggs, kind, pkey, basis, d, prices, volume, amount):
    agg = period_aggs[kind].setdefault((pkey, basis), {"first_date": d, "open": prices[0], "high": prices[1],
                                                       "low": prices[2], "close": prices[3], "volume": 0,
                                                       "amount": 0.0, "actual": 0, "max_date": d,
                                                       "digest": hashlib.sha256()})
    if d < agg["first_date"]:
        agg["first_date"], agg["open"] = d, prices[0]
    if prices[1] is not None:
        agg["high"] = prices[1] if agg["high"] is None else max(agg["high"], prices[1])
    if prices[2] is not None:
        agg["low"] = prices[2] if agg["low"] is None else min(agg["low"], prices[2])
    if d >= agg["max_date"]:
        agg["max_date"], agg["close"] = d, prices[3]
    agg["volume"] += volume
    agg["amount"] += amount
    agg["actual"] += 1
    fact = [d, *(str(p) if p is not None else None for p in prices), volume, repr(amount)]
    agg["digest"].update((json.dumps(fact, separators=(",", ":")) + "\n").encode())
    return agg

def evaluate_price_base(result, status, row, is_st, state, reference, events, service,
                        delist_dates_by_id, ambiguous_listing_date, first_listing_session_by_id, session_index):
    security_id = result['security_id']
    board = result['board_scope']
    day = result['trade_date'].replace('-', '')
    samples = {}
    boundary_days = set()
    if status == "SUSPENDED":
        result.update(limit_status="SUSPENDED", reference_basis="SUSPENSION_FACT", reason="SUSPENDED")
        state.carry_no_trade()
    elif status != "ACTUAL_TRADED":
        result["reason"] = "TRADING_STATUS_" + status
        state.invalidate("REFERENCE_STATE_UNAVAILABLE")
    elif row is None or str(row["trade_date"]) != day:
        result["reason"] = "ACTUAL_BAR_BINDING_MISSING"
    elif is_st not in {"0", "1"}:
        result["reason"] = "RISK_STATUS_UNKNOWN"
    else:
        risk_status = "RISK_WARNING" if is_st == "1" else "NORMAL"
        result["risk_status"] = risk_status
        if day in delist_dates_by_id.get(security_id, set()):
            result.update(reference_basis="UNKNOWN", reason="DELISTING_PHASE_UNRESOLVED")
        elif security_id not in ambiguous_listing_date:
            first_session = first_listing_session_by_id.get(security_id)
            if first_session is not None and first_session <= session_index[day] < first_session + 5:
                result.update(limit_status="NO_LIMIT", reference_basis="LISTING_PHASE", reason="IPO_FIRST_5_TRADING_DAYS")
                samples.setdefault("IPO_NO_LIMIT", dict(result))
                if row:
                    state.observe_actual_close(row["raw_close"])
                return result

        if day in delist_dates_by_id.get(security_id, set()):
            result.update(reference_basis="UNKNOWN", reason="DELISTING_PHASE_UNRESOLVED")
        elif security_id in ambiguous_listing_date:
            result.update(reference_basis="UNKNOWN", reason="LISTING_DATE_AMBIGUOUS")
        elif any(event.disposition in {"UNKNOWN_PRICE_IMPACT", "PRICE_AFFECTING_UNSUPPORTED"} for event in events):
            result.update(reference_basis="UNKNOWN", reason="CORPORATE_ACTION_REFERENCE_UNSUPPORTED")
        elif reference is None:
            result.update(reference_basis="UNKNOWN", reason=state.unknown_reason())
        else:
            ref = reference
            cat1_events = [event.event for event in events if event.event is not None]
            try:
                if cat1_events:
                    basis = "TDX_XRXD_REFERENCE_TRANSFORM_DIAGNOSTIC_NON_PIT"
                else:
                    basis = "PREVIOUS_OFFICIAL_CLOSE_STATE"
                exchange, rule_board = board_rule_key(board)
                limit = service.evaluate({
                    "security_id": security_id, "trade_date": day, "exchange": exchange,
                    "board": rule_board, "risk_status": risk_status, "suspended": False,
                    "reference_status": "KNOWN", "quote_prev_close": str(ref),
                    "close": str(row["raw_close"]), "listing_phase": "REGULAR",
                    "ex_rights_reference_unknown": False,
                })
                result.update(reference_price=str(ref), reference_basis=basis,
                              rule_id=limit.get("rule_id"),
                              limit_up_price=str(limit["limit_up_price"]) if limit.get("limit_up_price") is not None else None,
                              limit_down_price=str(limit["limit_down_price"]) if limit.get("limit_down_price") is not None else None,
                              limit_status=limit.get("limit_state", "UNKNOWN"), reason=limit.get("reason"))
                if cat1_events:
                    samples.setdefault("EX_RIGHT", {**result, "previous_close": str(ref),
                                                   "action_count": len(cat1_events),
                                                   "action_formula": "(previous_close-cash_dividend_per_share+rights_price*rights_ratio)/(1+bonus_transfer_ratio+rights_ratio)"})
            except Exception as exc:
                result.update(reference_basis="UNKNOWN", reason="REFERENCE_STATE_UNAVAILABLE:" + type(exc).__name__)

            # 2026-07-06 is the risk-warning ratio rule boundary.
            if day in boundary_days and risk_status == "RISK_WARNING":
                samples.setdefault("RULE_BOUNDARY_" + day + "_" + board, dict(result))
    return result
